class Solution {
    unordered_map<string, vector<int> > memo;

    vector<int> solve(const string& s) {
        if (memo.count(s))
            return memo[s];

        vector<int> ans;

        for (int i = 0; i < s.size(); ++i) {
            char op = s[i];

            if (op != '+' && op != '-' && op != '*')
                continue;

            vector<int> left = solve(s.substr(0, i));
            vector<int> right = solve(s.substr(i + 1));

            for (int a : left) {
                for (int b : right) {
                    if (op == '+')
                        ans.push_back(a + b);
                    else if (op == '-')
                        ans.push_back(a - b);
                    else
                        ans.push_back(a * b);
                }
            }
        }

        // No operator => the whole string is a number
        if (ans.empty())
            ans.push_back(stoi(s));

        return memo[s] = ans;
    }

public:
    vector<int> diffWaysToCompute(string expression) {
        return solve(expression);
    }
};
